const {questions,rank,explain}=window.EmotionModel;
const workspace=document.getElementById('workspace');
let answers=Array(10).fill(null),step=0,showingResults=false;
function render(focus=false){showingResults=false;workspace.classList.remove('result-workspace');const q=questions[step];const labels=q.labels||['Not at all','A little','Moderately','Quite a lot','Very much'];workspace.innerHTML=`<div class="progress-top"><strong>YOUR CHECK-IN</strong><span>Question ${String(step+1).padStart(2,'0')} / 10</span></div><div class="progress" aria-hidden="true">${questions.map((_,i)=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><div class="question-category">${q.category}</div><h2 id="question" tabindex="-1">${q.title}</h2><p class="hint" id="hint">${q.hint}</p><fieldset class="choices" aria-describedby="hint"><legend class="visually-hidden">${q.title}</legend>${labels.map((label,i)=>`<label class="choice"><input type="radio" name="answer" value="${i}" ${answers[step]===i?'checked':''}><span class="choice-label">${label}</span><span class="choice-key" aria-hidden="true">${String(i+1).padStart(2,'0')}</span></label>`).join('')}</fieldset><div class="actions"><button class="back" id="back" ${step===0?'disabled':''}>Back</button><button class="primary" id="next" ${answers[step]===null?'disabled':''}>${step===9?'Explore my feelings':'Continue'}</button></div><p class="micro">About 2 minutes · Take your time, and answer for right now.</p>`;workspace.querySelectorAll('input').forEach(input=>input.addEventListener('change',()=>{answers[step]=Number(input.value);document.getElementById('next').disabled=false;}));document.getElementById('back').onclick=()=>{step--;render(true);};document.getElementById('next').onclick=()=>{if(answers[step]===null)return;if(step===9)results();else{step++;render(true);}};if(focus)document.getElementById('question').focus();}
function results(){const matches=rank(answers);const best=matches[0];const close=matches[1].distance-best.distance<.35;const weak=best.distance>2;const reasons=explain(answers,best);showingResults=true;workspace.classList.add('result-workspace');workspace.innerHTML=`<span class="result-label">YOUR INNER WEATHER · A SNAPSHOT</span><h2 class="result-title" id="result-title" tabindex="-1">${best.name}</h2><p class="hint">${weak?'An approximate starting point — no description fits especially closely.':close?'A tentative closest match — a few feelings sit close together.':'The closest match in this check-in.'}</p><div class="result-copy">${best.description}<p>${best.meaning}</p></div><div class="why"><h3>What in your answers points here</h3>${reasons.length?`<ul>${reasons.map(r=>`<li>${r}</li>`).join('')}</ul>`:'<p class="alternatives-note">Your answers sit mostly in the middle. There is no strong signal, so treat these suggestions as words to explore.</p>'}</div><h3 class="alternatives-heading">Other feelings in the picture</h3><p class="alternatives-note">Three next-closest possibilities, with less support overall.${close?' The first is a near-tie with your main match.':''} Open each to explore.</p>${matches.slice(1,4).map((m,i)=>`<details><summary><span class="rank">0${i+2}</span><strong>${m.name}</strong><span class="fit">${m.distance-best.distance<.35?'Similar fit':'Less close'}</span></summary><p>${m.description}</p><p>${m.meaning}</p></details>`).join('')}<p class="result-footnote">These are relative matches from a simple questionnaire, not measured probabilities. Feelings can overlap, and you decide which words fit.</p><div class="result-actions"><button class="primary" id="review">Review my answers</button><button class="text-button" id="restart">New check-in</button></div>`;document.getElementById('review').onclick=()=>{step=0;render(true);};document.getElementById('restart').onclick=()=>{answers=Array(10).fill(null);step=0;render(true);};document.getElementById('result-title').focus();}
document.getElementById('about').onclick=()=>document.getElementById('info').showModal();document.getElementById('close-info').onclick=()=>document.getElementById('info').close();render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_emotion_checkin',description:'Read the current question and progress of the emotion check-in, or its completed result.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>showingResults?{complete:true,matches:rank(answers).slice(0,4).map(m=>({name:m.name,description:m.description}))}:{complete:false,questionNumber:step+1,question:questions[step].title,options:questions[step].labels||['Not at all','A little','Moderately','Quite a lot','Very much']}})).catch(()=>{});}catch{}}
